import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<Integer> unused = new ArrayList<>();
        for (int value : nums) {
            unused.add(value);
        }
        List<List<Integer>> result = new ArrayList<>();
        build(unused, new ArrayList<>(), result);
        return result;
    }

    private void build(List<Integer> unused, List<Integer> current, List<List<Integer>> result) {
        if (unused.isEmpty()) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int index = 0; index < unused.size(); index++) {
            int value = unused.get(index);
            List<Integer> nextUnused = new ArrayList<>(unused);
            nextUnused.remove(index);
            current.add(value);
            build(nextUnused, current, result);
            current.remove(current.size() - 1);
        }
    }
}

