import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        build(nums, 0, result);
        return result;
    }

    private void build(int[] nums, int index, List<List<Integer>> result) {
        if (index == nums.length) {
            List<Integer> permutation = new ArrayList<>();
            for (int value : nums) {
                permutation.add(value);
            }
            result.add(permutation);
            return;
        }
        for (int choice = index; choice < nums.length; choice++) {
            swap(nums, index, choice);
            build(nums, index + 1, result);
            swap(nums, index, choice);
        }
    }

    private void swap(int[] nums, int first, int second) {
        int temporary = nums[first];
        nums[first] = nums[second];
        nums[second] = temporary;
    }
}
